using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalWorkTests
{
    static string WorldSessionId(EntityId task,string suffix)=>"message:"+task.Value.Replace(':','/')+"/"+suffix;
    static WorldSession New()=>new(RegionalWork.Create());
    static EntityId Person(string node)=>RegionalWork.Roles.Single(r=>r.Node==node).Person;
    static void Go(WorldSession s,string node){if(TravelWorld.Origin(s.DiagnosticSnapshot(),ContractFixture.Officer)==node)return;var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:go/"+s.Revision,node);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);s.SetPaused(false);s.AdvanceTo(s.Seconds+1);s.AdvanceTo(s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);}
    static void Dispatch(WorldSession s,string node,int due=60)=>Assert.Equal(ResultCode.Accepted,s.Submit(RegionalWork.Build(s.DiagnosticSnapshot(),"request:work/"+s.Revision,Person(node),due),s.Revision).Code);
    static void Open(WorldSession s){Assert.Equal(ResultCode.Accepted,s.Open(ContractFixture.Officer,RegionalWork.Inbox(s).Last().Message,s.Revision).Code);}
    [Fact] public void ProfileHasNoFabricatedServiceOrCoerciveHistoricalAuthority(){var old=OfficerLoop.Create();var w=RegionalWork.Create();Assert.Equal(ContractJson.Write(old.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.Equal(ContractJson.Write(old.Offices),ContractJson.Write(w.Offices));Assert.Equal(ContractJson.Write(old.LandRights),ContractJson.Write(w.LandRights));Assert.Contains("1559",RegionalWork.Roles.Single(r=>r.Node=="odawara").Position);Assert.All(w.Grants.Where(g=>g.Basis==new EntityId("basis:regional-voluntary-inspection")),g=>{Assert.Equal(new[]{ActionKind.Inspect},g.Actions);Assert.Empty(g.Assets);Assert.Equal(0,g.Limit);});}
    [Theory][InlineData("castle")][InlineData("kofu")][InlineData("odawara")]
    public void TravelReceiveConsentAndReturnUseTheLocalFixedAddress(string node){var s=New();Go(s,node);Assert.Contains(Person(node),RegionalWork.NearbyDispatchers(s));Assert.True(RegionalWork.CanDispatch(s.DiagnosticSnapshot(),Person(node)));var at=s.Seconds;Dispatch(s,node);Assert.Empty(RegionalWork.Inbox(s));s.AdvanceTo(at+1);Assert.True(s.Paused);Assert.Null(RegionalWork.Inbox(s).Single().Task);Open(s);var task=s.DiagnosticSnapshot().Tasks.Last();Assert.Equal(AgreementPhase.AwaitingAssent,task.Agreement);Assert.Null(task.StartedAt);Assert.Equal(ResultCode.Accepted,s.Assent(task.Id,ContractFixture.Officer,true,s.Revision).Code);s.SetPaused(false);s.AdvanceTo(at+7);task=s.DiagnosticSnapshot().Tasks.Last();Assert.Equal(ExecutionPhase.Completed,task.Execution);Assert.Equal(ReportingPhase.KnownByRecipient,task.Report);Assert.Equal(2,s.DiagnosticSnapshot().Couriers!.Missions.Count(c=>c.Destination==node&&new[]{WorldSessionId(task.Id,"order"),WorldSessionId(task.Id,"report")}.Contains(s.DiagnosticSnapshot().Messaging.Attempts.Single(a=>a.Id==c.Attempt).MessageId)));Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Theory][InlineData(false)][InlineData(true)] public void DeclineAndExpiryNeverExecute(bool expire){var s=New();Dispatch(s,"castle",expire?2:60);s.AdvanceTo(1);Open(s);if(!expire)s.Assent(s.DiagnosticSnapshot().Tasks.Single().Id,ContractFixture.Officer,false,s.Revision);s.SetPaused(false);s.AdvanceTo(7);var t=s.DiagnosticSnapshot().Tasks.Single();Assert.Equal(ExecutionPhase.Stopped,t.Execution);Assert.Empty(s.DiagnosticSnapshot().EffectLedger);Assert.Equal(expire?AgreementPhase.Expired:AgreementPhase.Declined,t.Agreement);}
    [Fact] public void UnknownRemoteDispatcherCannotBeUsedAndRefusalIsNotLeaked(){var s=New();Assert.DoesNotContain(Person("kofu"),RegionalWork.NearbyDispatchers(s));var i=RegionalWork.Build(s.DiagnosticSnapshot(),"request:remote",Person("kofu"));Assert.NotEqual(ResultCode.Accepted,s.Submit(i,s.Revision).Code);var w=s.DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==w.PlayerControl?c with{WillObey=false}:c).ToArray();Assert.True(RegionalWork.CanDispatch(w,Person("castle")));}
    [Fact] public void ChangedScopeKindOrDurationCannotGrantHistoricalCoercion(){var s=New();var i=RegionalWork.Build(s.DiagnosticSnapshot(),"request:bad",Person("castle"));foreach(var bad in new[]{i with{Kind=TaskKind.BindingOrder},i with{Scope=new("site:kofu")},i with{WorkSeconds=1},i with{Actor=ContractFixture.Lord}})Assert.NotEqual(ResultCode.Accepted,s.Submit(bad,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Tasks);}
    [Fact] public void LostLocalOrderRetriesOnlyAfterPhysicalFailureAndSingleEffect(){var s=New();Go(s,"kofu");Dispatch(s,"kofu");var at=s.Seconds;var msg=s.DiagnosticSnapshot().Messaging.Messages.Last().Id;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,msg));s.AdvanceTo(at+2);s.DiagnosticTransport((m,t)=>MessageFlow.Retry(m,msg,Person("kofu").Value,t));s.AdvanceTo(at+3);Open(s);s.Assent(s.DiagnosticSnapshot().Tasks.Last().Id,ContractFixture.Officer,true,s.Revision);s.SetPaused(false);s.AdvanceTo(at+9);Assert.Single(s.DiagnosticSnapshot().EffectLedger,e=>e.Result=="completed"&&e.Task==s.DiagnosticSnapshot().Tasks.Last().Id);Assert.All(s.DiagnosticSnapshot().Couriers!.Missions.Where(c=>s.DiagnosticSnapshot().Messaging.Attempts.Single(a=>a.Id==c.Attempt).MessageId==msg),c=>Assert.Equal("kofu",c.Destination));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(5)] public void SaveAndContinuePreserveRealTravelAndWork(int phase){var s=New();Go(s,"kofu");var at=s.Seconds;Dispatch(s,"kofu");if(phase>0)s.AdvanceTo(at+1);if(phase>1){Open(s);s.Assent(s.DiagnosticSnapshot().Tasks.Last().Id,ContractFixture.Officer,true,s.Revision);s.SetPaused(false);s.AdvanceTo(at+phase);}var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"regional-work-"+Guid.NewGuid().ToString("N")),RegionalWork.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.25,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));foreach(var q in new[]{s,host.Current}){q.SetPaused(false);if(phase==0)q.AdvanceTo(at+1);if(phase<2){Open(q);q.Assent(q.DiagnosticSnapshot().Tasks.Last().Id,ContractFixture.Officer,true,q.Revision);q.SetPaused(false);}q.AdvanceTo(at+9);}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Tasks.Select(t=>t with{Revision=0}).ToArray()),ContractJson.Write(host.Current.DiagnosticSnapshot().Tasks.Select(t=>t with{Revision=0}).ToArray()));Assert.Equal(ContractJson.Write(RegionalWork.Inbox(s)),ContractJson.Write(RegionalWork.Inbox(host.Current)));}
    [Fact] public void ExpiringInspectionPermissionStopsEffectAndPhysicalReportStillReturns(){var w=RegionalWork.Create();w.Grants=w.Grants.Select(g=>g.Agent==Person("castle")?g with{Until=2}:g).ToArray();var s=new WorldSession(w);Dispatch(s,"castle");s.AdvanceTo(1);Open(s);s.Assent(s.DiagnosticSnapshot().Tasks.Single().Id,ContractFixture.Officer,true,s.Revision);s.SetPaused(false);s.AdvanceTo(7);Assert.DoesNotContain(s.DiagnosticSnapshot().EffectLedger,e=>e.Result=="completed");Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Equal(ReportingPhase.KnownByRecipient,s.DiagnosticSnapshot().Tasks.Single().Report);}
    [Fact] public void DuplicateSubmitAndOpenDoNotCreateSecondWork(){var s=New();var i=RegionalWork.Build(s.DiagnosticSnapshot(),"request:duplicate",Person("castle"));Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);s.AdvanceTo(1);Open(s);s.Assent(s.DiagnosticSnapshot().Tasks.Single().Id,ContractFixture.Officer,true,s.Revision);Assert.Equal(ResultCode.AlreadyAccepted,s.Open(ContractFixture.Officer,RegionalWork.Inbox(s).Single().Message,s.Revision).Code);s.SetPaused(false);s.AdvanceTo(7);Assert.Single(s.DiagnosticSnapshot().Tasks);Assert.Single(s.DiagnosticSnapshot().EffectLedger,e=>e.Result=="completed");}
    [Fact] public void OldProfileSaveIsNotSilentlyReinterpreted(){var s=new WorldSession(OfficerLoop.Create());var root=Path.Combine(Path.GetTempPath(),"regional-work-old-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(root,OfficerLoop.Create().Definitions).Save(s,"test",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,RegionalWork.Create().Definitions).Prepare("test"));}
}
